gU1(){return"\u0416\u043e\u049b. \u0422\u0435\u043a \u0430\u043b\u0493\u0430 \u0436\u04d9\u043d\u0435 \u043e\u04a3\u0493\u0430 \u0493\u0430\u043d\u0430 \u0440\u04b1\u049b\u0441\u0430\u0442 \u0435\u0442\u0456\u043b\u0435\u0434\u0456."},
gU4(){return"\u041c\u0435\u043d \u0441\u043e\u043b \u0436\u0430\u049b \u0436\u043e\u043b\u0430\u049b\u0442\u0430\u043d \u0431\u04b1\u0440\u044b\u043b\u0430 \u0430\u043b\u0430\u043c\u044b\u043d \u0431\u0430?"},
gU3(){return"\u0418\u04d9. \u0420\u04b1\u049b\u0441\u0430\u0442 \u0435\u0442\u0456\u043b\u0433\u0435\u043d \u0441\u043e\u043b\u0493\u0430 \u0431\u04b1\u0440\u044b\u043b\u0443 \u0441\u043e\u043d\u044b\u043c\u0435\u043d \u049b\u0430\u0442\u0430\u0440 \u043a\u0435\u0440\u0456 \u0431\u04b1\u0440\u044b\u043b\u0443\u0493\u0430 \u043c\u04af\u043c\u043a\u0456\u043d\u0434\u0456\u043a \u0431\u0435\u0440\u0435\u0434\u0456."},
gU6(){return u.X},
