ga59(){return"\u041c\u04b1\u0437\u0434\u0430 \u043a\u04af\u0440\u0442 \u04d9\u0440\u0435\u043a\u0435\u0442 \u0436\u0430\u0441\u0430\u043c\u0430\u04a3\u044b\u0437"},
ga58(){return"\u0416\u044b\u043b\u0434\u0430\u043c\u0434\u044b\u049b\u0442\u044b \u0430\u043b\u0434\u044b\u043d \u0430\u043b\u0430 \u0430\u0437\u0430\u0439\u0442\u044b\u04a3\u044b\u0437. \u0420\u0443\u043b\u044c \u043c\u0435\u043d \u043f\u0435\u0434\u0430\u043b\u044c\u0434\u0430\u0440\u0434\u044b \u0431\u0456\u0440\u049b\u0430\u043b\u044b\u043f\u0442\u044b \u049b\u043e\u043b\u0434\u0430\u043d\u044b\u043f, \u0430\u0440\u0430\u049b\u0430\u0448\u044b\u049b\u0442\u044b\u049b\u0442\u044b \u04b1\u043b\u0493\u0430\u0439\u0442\u044b\u04a3\u044b\u0437."},
ga5b(){return"ABS \u0431\u043e\u043b\u0441\u0430, \u0442\u0435\u0436\u0435\u0433\u0456\u0448\u0442\u0456 \u0431\u0430\u0441\u044b\u043f \u04b1\u0441\u0442\u0430\u04a3\u044b\u0437"},
ga5a(){return"\u0428\u04b1\u0493\u044b\u043b \u0442\u0435\u0436\u0435\u0433\u0435\u043d\u0434\u0435 \u043f\u0435\u0434\u0430\u043b\u044c\u0434\u044b \u049b\u0430\u0442\u0442\u044b \u0431\u0430\u0441\u044b\u043f, \u04b1\u0441\u0442\u0430\u043f \u0442\u04b1\u0440\u044b\u04a3\u044b\u0437. \u041f\u0435\u0434\u0430\u043b\u044c\u0434\u044b\u04a3 \u0434\u0456\u0440\u0456\u043b\u0456 \u2014 ABS \u0436\u04af\u0439\u0435\u0441\u0456\u043d\u0456\u04a3 \u049b\u0430\u043b\u044b\u043f\u0442\u044b \u0436\u04b1\u043c\u044b\u0441\u044b."},
ga5d(){return"\u0422\u043e\u049b\u0442\u0430\u0443 \u0441\u044b\u0437\u044b\u0493\u044b\u043d\u0430 \u0434\u0435\u0439\u0456\u043d \u0442\u043e\u049b\u0442\u0430\u04a3\u044b\u0437"},
ga5c(){return"\u0422\u044b\u0439\u044b\u043c \u0441\u0430\u043b\u0430\u0442\u044b\u043d \u0441\u0438\u0433\u043d\u0430\u043b\u0434\u0430 \u0442\u043e\u049b\u0442\u0430\u0443 \u0441\u044b\u0437\u044b\u0493\u044b\u043d\u0430 \u043d\u0435\u043c\u0435\u0441\u0435 6.16 \u0431\u0435\u043b\u0433\u0456\u0441\u0456\u043d\u0435 \u0434\u0435\u0439\u0456\u043d \u0442\u043e\u049b\u0442\u0430\u04a3\u044b\u0437. \u0416\u0430\u044f\u0443 \u04e9\u0442\u043a\u0435\u043b\u0433\u0435 \u043a\u0456\u0440\u043c\u0435\u04a3\u0456\u0437."},
ga5f(){return"\u0416\u04af\u043a \u043a\u04e9\u043b\u0456\u0433\u0456\u043d\u0435 \u0442\u044b\u043c \u0436\u0430\u049b\u044b\u043d\u0434\u0430\u043c\u0430\u04a3\u044b\u0437"},
ga5e(){return"\u0410\u043b\u0434\u0430\u0493\u044b \u0436\u043e\u043b\u0434\u044b \u043a\u04e9\u0440\u0443 \u04af\u0448\u0456\u043d \u0436\u0435\u0442\u043a\u0456\u043b\u0456\u043a\u0442\u0456 \u0430\u0440\u0430\u043b\u044b\u049b \u049b\u0430\u043b\u0434\u044b\u0440\u044b\u04a3\u044b\u0437. \u0416\u043e\u043b \u043a\u04e9\u0440\u0456\u043d\u0431\u0435\u0441\u0435, \u0431\u0430\u0441\u044b\u043f \u043e\u0437\u0443\u0434\u044b \u0431\u0430\u0441\u0442\u0430\u043c\u0430\u04a3\u044b\u0437."},
