ga5g(){return"1.13 \u043d\u0435 1.14 \u0431\u0435\u043b\u0433\u0456\u0441\u0456 \u0431\u0430\u0440 \u0435\u04a3\u0456\u0441\u0442\u0435 \u043a\u0435\u0434\u0435\u0440\u0433\u0456 \u049b\u0430\u0440\u0441\u044b \u043a\u04e9\u043b\u0456\u043a\u043f\u0435\u043d \u04e9\u0442\u0443\u0433\u0435 \u0431\u04e9\u0433\u0435\u0442 \u0431\u043e\u043b\u0441\u0430, \u0442\u04e9\u043c\u0435\u043d \u0442\u04af\u0441\u0456\u043f \u043a\u0435\u043b\u0435 \u0436\u0430\u0442\u049b\u0430\u043d \u0436\u04af\u0440\u0433\u0456\u0437\u0443\u0448\u0456 \u0436\u043e\u043b \u0431\u0435\u0440\u0435\u0434\u0456."},
ga4G(){return"\u0416\u0430\u0441\u044b\u043b \u0436\u0430\u043d\u0441\u0430 \u0434\u0430, \u0436\u043e\u043b\u0434\u044b \u0442\u0435\u043a\u0441\u0435\u0440\u0456\u04a3\u0456\u0437"},
ga4F(){return"\u049a\u0438\u044b\u043b\u044b\u0441\u0442\u0430\u043d \u04e9\u0442\u0456\u043f \u04af\u043b\u0433\u0435\u0440\u043c\u0435\u0433\u0435\u043d \u043a\u04e9\u043b\u0456\u043a\u0442\u0435\u0440 \u043c\u0435\u043d \u04e9\u0442\u043a\u0435\u043b\u0434\u0435\u043d \u04e9\u0442\u0443\u0434\u0456 \u0430\u044f\u049b\u0442\u0430\u043f \u0436\u0430\u0442\u049b\u0430\u043d \u0436\u0430\u044f\u0443 \u0436\u04af\u0440\u0433\u0456\u043d\u0448\u0456\u043b\u0435\u0440\u0433\u0435 \u0436\u043e\u043b \u0431\u0435\u0440\u0456\u04a3\u0456\u0437."},
