ga4V(){return"\u0416\u0430\u049b\u044b\u043d \u0436\u0430\u0440\u044b\u049b\u0442\u044b \u049b\u043e\u0441\u044b\u043f, \u0436\u044b\u043b\u0434\u0430\u043c\u0434\u044b\u049b\u0442\u044b \u0430\u0437\u0430\u0439\u0442\u044b\u04a3\u044b\u0437 \u0436\u04d9\u043d\u0435 \u0430\u0440\u0430\u043b\u044b\u049b\u0442\u044b \u04b1\u043b\u0493\u0430\u0439\u0442\u044b\u04a3\u044b\u0437. \u041a\u04e9\u0440\u0456\u043d\u0443 \u0436\u0430\u049b\u0441\u0430\u0440\u0493\u0430\u043d\u0434\u0430 \u0442\u04b1\u043c\u0430\u043d \u0448\u0430\u043c\u0434\u0430\u0440\u044b\u043d \u04e9\u0448\u0456\u0440\u0456\u04a3\u0456\u0437."},
ga4Y(){return"\u0410\u043f\u0430\u0442 \u0431\u0435\u043b\u0433\u0456\u0441\u0456: \u043a\u0435\u043c\u0456\u043d\u0434\u0435 15 \u043d\u0435 30 \u043c"},
ga4X(){return"\u0420\u0435\u0441\u0435\u0439\u0434\u0435 \u0435\u043b\u0434\u0456 \u043c\u0435\u043a\u0435\u043d\u0434\u0435 \u2014 \u043a\u0435\u043c\u0456\u043d\u0434\u0435 15 \u043c, \u043e\u0434\u0430\u043d \u0442\u044b\u0441 \u2014 30 \u043c. \u041a\u04e9\u0440\u0456\u043d\u0443 \u043d\u0430\u0448\u0430\u0440 \u0431\u043e\u043b\u0441\u0430, \u0431\u0435\u043b\u0433\u0456\u043d\u0456 \u0430\u043b\u044b\u0441\u044b\u0440\u0430\u049b \u049b\u043e\u0439\u044b\u04a3\u044b\u0437."},
ga51(){return"\u04b0\u0439\u049b\u044b \u043a\u0435\u043b\u0441\u0435, \u0442\u043e\u049b\u0442\u0430\u04a3\u044b\u0437"},
